            var dd = String(today.getDate()).padStart(2, '0');
            var mm = String(today.getMonth() + 1).padStart(2, '0'); //January is 0!
            var yyyy = today.getFullYear();

            today = mm + '/' + dd + '/' + yyyy;

            document.getElementById("DisplayDate").innerHTML = today;

            $('#styleOptions').styleSwitcher({
                hasPreview: false,
                fullPath: '../Portal/assets/css/'
            });

            if (location.hostname == "localhost") {
                $('#divLocal').show();
                $('#divStaging').hide();
                $('#divProd').hide();
            }
            else if (location.hostname == "raman-coe.mapit.gov.in") {
                $('#divLocal').hide();
                $('#divStaging').show();
                $('#divProd').hide();
            }
            else if (location.hostname == "highereducation.mp.gov.in") {
